module FractionalN_PLL (
    input wire clk,
    input wire reset,
    input wire [15:0] fractional_input,
    output reg vco_out
);

reg [31:0] phase_accumulator;
reg [15:0] phase_error;
reg [15:0] loop_filter_output;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        phase_accumulator <= 32'b0;
        vco_out <= 1'b0;
    end else begin
        phase_accumulator <= phase_accumulator + fractional_input;
        phase_error <= phase_accumulator[15:0];  // Simplified phase error calculation
        loop_filter_output <= loop_filter_output + phase_error;  // Simple loop filter
        vco_out <= loop_filter_output[15];  // VCO output based on the loop filter output
    end
end

endmodule

