module pitch_detector (  
    input clk,  
    input reset,  
    input [7:0] audio_signal,  
    input [7:0] threshold,  
    output reg pitch_detected  
);  
    reg [3:0] counter;  
    parameter WINDOW_SIZE = 4;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            pitch_detected <= 0;  
            counter <= 0;  
        end else begin  
            if (audio_signal > threshold) begin  
                if (counter < WINDOW_SIZE) begin  
                    counter <= counter + 1;  
                end  
                if (counter == WINDOW_SIZE) begin  
                    pitch_detected <= 1;  
                end  
            end else begin  
                counter <= 0;  
                pitch_detected <= 0;  
            end  
        end  
    end  
endmodule

