module serializer_16bit(  
    input clk,  
    input rst,  
    input [15:0] data_in,  
    output reg serial_out  
);  
    reg [3:0] count;  
    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            count <= 4'b0;  
            serial_out <= 1'b0;  
        end else begin  
            if (count < 4'd16) begin  
                serial_out <= data_in[15 - count];  
                count <= count + 1;  
            end else begin  
                serial_out <= 1'b0; // Maintain the last bit after serialization  
            end  
        end  
    end  
endmodule

