module adaptive_lms_filter(
    input clk,
    input reset,
    input [15:0] x,        // Input signal
    input [15:0] d,        // Desired signal
    input [15:0] mu,       // Step size
    output reg [15:0] y,   // Output signal
    output reg [15:0] e     // Error signal
);
    reg [15:0] w [0:3];     // Coefficients
    reg [15:0] x_buf [0:3]; // Input buffer
    integer i;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            y <= 0;
            e <= 0;
            for (i = 0; i < 4; i = i + 1) begin
                w[i] <= 0;
                x_buf[i] <= 0;
            end
        end else begin
            // Shift input buffer
            for (i = 3; i > 0; i = i - 1) begin
                x_buf[i] <= x_buf[i - 1];
            end
            x_buf[0] <= x;

            // Calculate output
            y <= w[0] * x_buf[0] + w[1] * x_buf[1] + w[2] * x_buf[2] + w[3] * x_buf[3];

            // Calculate error
            e <= d - y;

            // Update coefficients
            for (i = 0; i < 4; i = i + 1) begin
                w[i] <= w[i] + mu * e * x_buf[i];
            end
        end
    end
endmodule

