module serializer (
    input clk,
    input rst,
    input [31:0] data_in,
    output reg serial_out,
    output reg done
);
    reg [4:0] bit_index; // 5 bits to count from 0 to 31

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            bit_index <= 0;
            serial_out <= 0;
            done <= 0;
        end else if (bit_index < 32) begin
            serial_out <= data_in[31 - bit_index]; // output the bits in reverse order
            bit_index <= bit_index + 1;
            done <= 0;
        end else begin
            done <= 1; // signal that serialization is complete
        end
    end
endmodule

