module spi_master (
    input clk,
    input reset,
    input start,
    input [7:0] data_in,
    output reg [7:0] data_out,
    output reg busy,
    output reg done,
    output reg sclk,
    input miso
);
    reg [2:0] bit_cnt;
    reg [7:0] shift_reg;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            busy <= 0;
            done <= 0;
            sclk <= 0;
            bit_cnt <= 0;
            data_out <= 0;
            shift_reg <= 0;
        end else begin
            if (start && !busy) begin
                busy <= 1;
                done <= 0;
                shift_reg <= data_in;
                bit_cnt <= 7;
            end else if (busy) begin
                if (bit_cnt >= 0) begin
                    sclk <= 1; // Drive clock high
                    data_out[bit_cnt] <= miso; // Read from MISO
                    #5; // Simulate clock period
                    sclk <= 0; // Drive clock low
                    shift_reg <= {shift_reg[6:0], 1'b0}; // Shift register
                    bit_cnt <= bit_cnt - 1;
                end else begin
                    busy <= 0;
                    done <= 1;
                end
            end
        end
    end
endmodule

