module Fractional_N_PLL (
    input wire clk_in,
    input wire rst,
    input wire [7:0] fractional_value,
    output reg clk_out
);
    reg [7:0] counter;
    reg [7:0] divisor;

    always @(posedge clk_in or posedge rst) begin
        if (rst) begin
            counter <= 0;
            clk_out <= 0;
        end else begin
            counter <= counter + 1;
            if (counter >= divisor) begin
                clk_out <= ~clk_out;
                counter <= 0;
            end
        end
    end

    always @(fractional_value) begin
        divisor = 8'd100 / fractional_value; // Simple calculation for division
    end
endmodule

