module instruction_pipeline (  
    input clk,  
    input reset,  
    input [15:0] instruction_in,  
    output reg [15:0] fetch_out,  
    output reg [15:0] decode_out,  
    output reg [15:0] execute_out,  
    output reg [15:0] write_back_out  
);  

    reg [15:0] fetch_reg;  
    reg [15:0] decode_reg;  
    reg [15:0] execute_reg;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            fetch_reg <= 16'b0;  
            decode_reg <= 16'b0;  
            execute_reg <= 16'b0;  
            fetch_out <= 16'b0;  
            decode_out <= 16'b0;  
            execute_out <= 16'b0;  
            write_back_out <= 16'b0;  
        end else begin  
            fetch_out <= fetch_reg;  
            decode_out <= decode_reg;  
            execute_out <= execute_reg;  
            write_back_out <= execute_reg;  

            fetch_reg <= instruction_in;  
            decode_reg <= fetch_reg;  
            execute_reg <= decode_reg;  
        end  
    end  
endmodule

