module watchdog_timer(  
    input clk,  
    input reset,  
    input [3:0] timeout_value,  
    output reg timeout_event  
);  
    reg [3:0] counter;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            counter <= 0;  
            timeout_event <= 0;  
        end else begin  
            if (counter < timeout_value) begin  
                counter <= counter + 1;  
                timeout_event <= 0;  
            end else begin  
                timeout_event <= 1;  
            end  
        end  
    end  
endmodule

