module pll_4x (
    input wire clk_in,
    input wire reset,
    output reg clk_out
);

reg [1:0] counter;
reg clk_div;

// Frequency divider (2x)
always @(posedge clk_in or posedge reset) begin
    if (reset) begin
        counter <= 2'b00;
        clk_div <= 0;
    end else begin
        counter <= counter + 1;
        if (counter == 2'b01) begin
            clk_div <= ~clk_div; // Toggle clk_div every 2 counts
        end
    end
end

// PLL output generation (4x)
always @(posedge clk_div or posedge reset) begin
    if (reset) begin
        clk_out <= 0;
    end else begin
        clk_out <= ~clk_out; // Toggle clk_out every 1 count of clk_div
    end
end

endmodule

