module interrupt_controller(  
    input wire clk,  
    input wire RESET,  
    input wire [3:0] IRQ,  
    output reg INT,  
    output reg ACK  
);  

reg [1:0] current_irq;  

always @(posedge clk or posedge RESET) begin  
    if (RESET) begin  
        INT <= 0;  
        ACK <= 0;  
        current_irq <= 0;  
    end else begin  
        if (IRQ[0]) begin  
            current_irq <= 2'b00;  
        end else if (IRQ[1]) begin  
            current_irq <= 2'b01;  
        end else if (IRQ[2]) begin  
            current_irq <= 2'b10;  
        end else if (IRQ[3]) begin  
            current_irq <= 2'b11;  
        end else begin  
            current_irq <= 2'b00;  
        end  

        if (current_irq != 2'b00) begin  
            INT <= 1;  
            ACK <= 1;  
        end else begin  
            INT <= 0;  
            ACK <= 0;  
        end  
    end  
end  
endmodule

