module carrier_recovery(input clk, input reset, input signal_in, output reg recovered_clk);  
    reg [1:0] phase;  
    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            phase <= 2'b00;  
            recovered_clk <= 0;  
        end else begin  
            // Simple phase detection logic  
            if (signal_in) begin  
                if (phase == 2'b00) begin  
                    recovered_clk <= 1;  
                    phase <= 2'b01;  
                end else begin  
                    recovered_clk <= 0;  
                    phase <= 2'b00;  
                end  
            end else begin  
                recovered_clk <= 0;  
                phase <= 2'b00;  
            end  
        end  
    end  
endmodule

