module pll_2x (
    input clk_in,
    input reset,
    output reg clk_out
);
    reg [1:0] state;

    // State encoding
    localparam IDLE = 2'b00, 
               HIGH = 2'b01, 
               LOW = 2'b10;

    always @(posedge clk_in or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            clk_out <= 0;
        end else begin
            case (state)
                IDLE: begin
                    clk_out <= 0;
                    state <= HIGH;
                end
                HIGH: begin
                    clk_out <= 1;
                    state <= LOW;
                end
                LOW: begin
                    clk_out <= 0;
                    state <= HIGH;
                end
            endcase
        end
    end
endmodule

