module pitch_detector (  
    input clk,  
    input reset,  
    input [15:0] audio_sample,  
    output reg pitch_detected  
);  
    parameter MIN_FREQ = 440; // Minimum frequency (A4)  
    parameter MAX_FREQ = 880; // Maximum frequency (A5)  
    reg [15:0] sample_buffer;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            sample_buffer <= 0;  
            pitch_detected <= 0;  
        end else begin  
            sample_buffer <= audio_sample;  
            if (sample_buffer >= MIN_FREQ && sample_buffer <= MAX_FREQ)  
                pitch_detected <= 1;  
            else  
                pitch_detected <= 0;  
        end  
    end  
endmodule

