module instruction_pipeline (
    input [4:0] instruction,
    input clk,
    input rst,
    output reg [4:0] out_instruction
);
    reg [4:0] if_stage;
    reg [4:0] id_stage;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            out_instruction <= 5'b0;
            if_stage <= 5'b0;
            id_stage <= 5'b0;
        end else begin
            // Fetch stage
            if_stage <= instruction;
            // Decode stage
            id_stage <= if_stage;
            // Execute stage
            out_instruction <= id_stage;
        end
    end
endmodule

