module crc_generator (  
    input clk,  
    input rst,  
    input [15:0] data_in,  
    input [15:0] polynomial,  
    output reg [15:0] crc_out  
);  

    reg [15:0] crc;  
    integer i;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            crc <= 16'b0;  
        end else begin  
            crc = data_in;  
            for (i = 15; i >= 0; i = i - 1) begin  
                if (crc[15] ^ data_in[i]) begin  
                    crc = crc ^ polynomial;  
                end  
                crc = crc << 1;  
            end  
            crc_out <= crc;  
        end  
    end  
endmodule

